"""Build a local, offline design tasting gallery. All workload figures are fixtures."""
from pathlib import Path
import base64
import html
import json

ROOT = Path(__file__).resolve().parents[3]
OUT = ROOT / 'artifacts/design-skill-gallery'
OUT.mkdir(parents=True, exist_ok=True)
HERE = Path(__file__).parent
SAMPLES = []
BASE = '''
*{box-sizing:border-box}body{margin:0;background:var(--bg,#fff);color:var(--ink,#1d1d1f);font:15px/1.55 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:32px}h1,h2,h3,p{margin:0}h1{font-size:30px;line-height:1.15;letter-spacing:-.025em}h2{font-size:19px;margin-bottom:16px}h3{font-size:15px}p{max-width:75ch}.sub{color:var(--mut,#666);margin-top:8px}.demo{font-size:12px;color:var(--mut,#666);margin-bottom:24px}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.between{justify-content:space-between}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:24px 0}.metric{padding:20px;background:var(--panel,#f5f5f7);border-radius:12px}.metric strong{display:block;font-size:32px;font-weight:600;letter-spacing:-.04em}.metric span{font-size:13px;color:var(--mut,#666)}.panel{padding:24px;border-radius:16px;background:var(--panel,#f5f5f7);margin-top:16px}.split{display:grid;grid-template-columns:1.5fr 1fr;gap:24px}.small{font-size:12px;color:var(--mut,#666)}button,select,input,textarea{font:inherit}button,select{cursor:pointer;border:1px solid var(--line,#ddd);border-radius:8px;padding:8px 14px;background:var(--panel,#fff);color:inherit}button:active{transform:scale(.97)}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #007aff;outline-offset:3px}button.primary{background:var(--accent,#007aff);color:#fff;border-color:transparent}button[aria-pressed=true]{background:var(--accent,#007aff);color:white}.segment{display:flex;background:var(--panel,#eee);padding:3px;border-radius:10px}.segment button{border:0;padding:5px 14px;background:transparent}.segment button[aria-pressed=true]{background:var(--ink,#1d1d1f);color:var(--bg,#fff)}table{width:100%;border-collapse:collapse;text-align:left}th{font-weight:500;color:var(--mut,#666);font-size:12px}td,th{padding:11px 8px;border-bottom:1px solid var(--line,#e4e4e7)}td:last-child,th:last-child{text-align:right}.scroll{overflow-x:auto}svg{display:block;width:100%;height:auto}svg text{font-family:system-ui,sans-serif;fill:currentColor}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;color:var(--mut,#666)}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:6px;background:var(--accent,#007aff)}.note{padding:16px 0;border-top:1px solid var(--line,#ddd);margin-top:24px;color:var(--mut,#666);font-size:13px}a{color:var(--accent,#007aff)}[hidden]{display:none!important}@media(max-width:650px){main{padding:20px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.split{grid-template-columns:1fr}h1{font-size:26px}.panel{padding:16px}.metric{padding:14px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}@media print{body{background:white!important;color:black!important}.no-print,button,select{display:none!important}.panel,.metric{background:#fff!important;border:1px solid #ccc;break-inside:avoid}main{padding:0}*{print-color-adjust:exact}}
'''

def page(title, body, css='', js=''):
    return f'<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{BASE}{css}</style><body>{body}' + (f'<script>{js}</script>' if js else '') + '</body></html>'

def add(slug, title, source, technique, body, css='', js='', caveat=''):
    doc = page(title, body, css, js)
    (OUT / f'{slug}.html').write_text(doc)
    SAMPLES.append(dict(id=slug,title=title,source=source,technique=technique,caveat=caveat,html=doc))

def metrics():
    return '<div class="grid">'+''.join(f'<div class="metric"><strong style="color:{c}">{v}</strong><span>{s}</span></div>' for v,s,c in [('24','задачи за неделю','#007aff'),('18','завершены','#248642'),('4','в работе','#b16b00'),('2','ждут решения','#ba475d')])+'</div>'

TABLE = '''<div class="scroll"><table><thead><tr><th>Задача</th><th>Состояние</th><th>Владелец</th></tr></thead><tbody><tr><td>Поиск по журналу</td><td>Готово</td><td>worker</td></tr><tr><td>Восстановление очереди</td><td>В работе</td><td>full-cycle</td></tr><tr><td>Выбор оформления</td><td>Ждёт решения</td><td>Владелец</td></tr></tbody></table></div>'''

def chart():
    return '''<svg viewBox="0 0 760 235" role="img" aria-labelledby="chart-title chart-desc"><title id="chart-title">Завершённые задачи за учебную неделю</title><desc id="chart-desc">По дням: 1, 2, 1, 3, 4, 3, 4. Всего 18 задач. Данные вымышлены.</desc><g stroke="currentColor" opacity=".1"><path d="M40 30H740M40 80H740M40 130H740M40 180H740"/></g><g font-size="12" opacity=".6"><text x="15" y="184">0</text><text x="15" y="134">2</text><text x="15" y="84">4</text><text x="15" y="34">6</text><text x="40" y="210">Пн</text><text x="153" y="210">Вт</text><text x="267" y="210">Ср</text><text x="381" y="210">Чт</text><text x="495" y="210">Пт</text><text x="609" y="210">Сб</text><text x="720" y="210">Вс</text></g><path d="M48 155L162 130L276 155L390 105L504 80L618 105L732 80V180H48Z" fill="var(--accent,#007aff)" opacity=".08"/><path d="M48 155L162 130L276 155L390 105L504 80L618 105L732 80" stroke="var(--accent,#007aff)" stroke-width="3" fill="none"/><g fill="var(--accent,#007aff)"><circle cx="48" cy="155" r="4"/><circle cx="162" cy="130" r="4"/><circle cx="276" cy="155" r="4"/><circle cx="390" cy="105" r="4"/><circle cx="504" cy="80" r="4"/><circle cx="618" cy="105" r="4"/><circle cx="732" cy="80" r="4"/></g></svg>'''

HEADER = '<p class="demo">Учебный пример. Числа и задачи придуманы для сравнения дизайна.</p>'
dashboard = HEADER+'<div class="row between"><div><h1>Команда за неделю</h1><p class="sub">Завершены 18 задач. Две ждут твоего решения.</p></div><div class="segment no-print"><button aria-pressed="true" data-view="overview">Обзор</button><button aria-pressed="false" data-view="tasks">Задачи</button></div></div>'+metrics()+'<section id="overview"><div class="panel"><h2>Завершено по дням</h2>'+chart()+'<div class="legend"><span><i class="dot"></i>Задачи, шт.</span><span>Учебная неделя, пн–вс</span></div></div><div class="panel"><h2>Нужен выбор</h2><div class="row between"><p>Какой стиль оставить для отчётов?</p><span class="small">Дизайн выбирает человек</span></div></div></section><section id="tasks" hidden><div class="panel"><h2>Примеры задач</h2>'+TABLE+'</div></section>'
tabs = "document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('section[id]').forEach(s=>s.hidden=s.id!==b.dataset.view)});"
add('01-apple','Белый рабочий стол','apple-design + референс пользователя','Плотная раскладка, цветные числа, спокойный фон, мгновенная обратная связь кнопок.', '<main>'+dashboard+'</main>', ':root{--bg:#f5f5f7;--panel:#fff;--ink:#1d1d1f;--mut:#6e6e73;--accent:#007aff;--line:#e8e8ed}h1{font-size:23px;font-weight:650}.metric strong{font-size:26px}.metric{padding:16px}.panel{border-radius:14px}main{padding:26px}.panel h2{font-size:15px}.segment{background:#e8e8ed}.metric span{font-size:12px}',tabs,caveat='Взята плотность указанной доски. Это новый макет с учебными данными, не копия её статистики.')

add('02-local','Наш проектный HTML','html-artifacts: .codex и .claude проекта','Две шрифтовые семьи, сдержанный акцент, плотный отчёт и табличная подача.', '<main>'+HEADER+'<h1>За неделю закрыто 18 задач</h1><p class="sub">Две задачи ждут решения владельца. Отчёт показывает состояние, а не причину задержек.</p>'+metrics()+'<div class="split"><section><h2>Движение за неделю</h2>'+chart()+'</section><section><h2>Что требует внимания</h2><p>Выбрать оформление отчётов и согласовать следующий этап. В учебных данных нет времени ожидания, поэтому оценивать скорость команды нельзя.</p></section></div><div class="note">Статус задач</div>'+TABLE+'</main>', ':root{color-scheme:light dark;--bg:light-dark(#fff,#181818);--ink:light-dark(#1a1c1f,#f2f2f0);--panel:light-dark(#f5f5f5,#242424);--mut:light-dark(#656565,#b8b8b8);--line:light-dark(#ddd,#444);--accent:light-dark(#236776,#82cfdf)}h1,h2{font-family:Georgia,serif;font-weight:500}.metric{border-radius:4px}.metric strong{font-size:27px}.grid{margin-bottom:32px}main{max-width:1080px}',caveat='Две проектные копии различаются путём сохранения; отдельного визуального варианта это не даёт.')

add('03-global','Глобальный HTML','html-artifacts: ~/.claude/skills','Тёмный инструмент, метрики сверху, график и таблица; переключаемые представления.', '<main>'+dashboard+'</main>', ':root{color-scheme:dark;--bg:#0e0e12;--panel:#19191f;--ink:#f1f1f4;--mut:#aaaab6;--line:#32323b;--accent:#9d78ed}.metric,.panel{border:1px solid var(--line);border-radius:6px}.metric strong{color:#c0a8fa!important}h1{font-size:29px}body{font-size:14px}',tabs,caveat='Показана тёмная исходная эстетика для сравнения. Твоя предпочтительная белая тема не заменяется этим вариантом.')

add('04-expressive','Выразительная обложка','frontend-design: глобальные версии Claude / Agents','Одна крупная типографическая композиция, асимметрия, насыщенный фон, минимум хрома.', '<main>'+HEADER+'<div class="poster"><div><h1>Работа<br>обретает<br>форму.</h1><p>18 задач завершены.<br>Ещё шесть — в движении.</p><a href="#details">Посмотреть состав недели</a></div><div class="sculpture" aria-label="18 завершённых задач из 24"><span>18</span><small>из 24</small><i></i></div></div><section id="details"><div class="row between"><h2>Неделя команды</h2><p>18 готово / 4 в работе / 2 ждут</p></div>'+TABLE+'</section></main>', ':root{--bg:#edffb8;--ink:#203523;--mut:#4b604d;--accent:#204e30;--panel:#e0f4a5;--line:#aec487}.poster{display:grid;grid-template-columns:1.1fr 1fr;align-items:center;min-height:500px;gap:20px}.poster h1{font-family:Georgia,serif;font-size:clamp(50px,7vw,88px);font-weight:400;line-height:.97;letter-spacing:-.065em}.poster p{margin:24px 0;font-size:19px}.sculpture{aspect-ratio:1;position:relative;border:2px solid #204e30;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-direction:column}.sculpture:before{content:"";position:absolute;inset:9%;border:1px solid #204e30;border-radius:50%}.sculpture span{font-size:clamp(90px,15vw,170px);line-height:1;letter-spacing:-.1em;font-weight:300}.sculpture small{font-size:18px}.sculpture i{position:absolute;width:18%;height:18%;border-radius:50%;background:#204e30;right:3%;top:9%}section{padding:32px 0;margin-top:24px;border-top:2px solid #204e30}@media(max-width:650px){.poster{grid-template-columns:1fr}.sculpture{width:70%;margin:24px auto}}',caveat='Это обложка или лендинг. Для ежедневной плотной статистики крупная композиция съедает полезное место.')

add('05-restrained','Сдержанный продукт','frontend-design: официальный marketplace','Сначала рабочая задача: увидеть, где нужен человек. Один заметный элемент — полоса состояния.', '<main>'+HEADER+'<header class="row between"><h1>Что осталось на этой неделе</h1><span class="small">Учебный срез</span></header><div class="statusbar" role="img" aria-label="18 задач готово, 4 в работе, 2 ждут"><span style="flex:18;background:#5a7975"></span><span style="flex:4;background:#9fb2cc"></span><span style="flex:2;background:#d7a463"></span></div><div class="legend"><span>18 завершены</span><span>4 в работе</span><span>2 ждут решения</span></div><section class="decision"><span class="count">2</span><div><h2>Только здесь нужен ты</h2><p>Выбрать оформление отчётов.<br>Согласовать следующий этап.</p></div></section><div class="split"><section><h2>Команда продолжает работу</h2>'+TABLE+'</section><aside><h2>Почему такой порядок</h2><p class="sub">Сначала видны решения, которые зависят от владельца. Закрытые задачи остаются в общей картине, но не требуют внимания.</p></aside></div></main>', ':root{--bg:#fff;--ink:#23312f;--mut:#65726f;--accent:#526f6a;--line:#e4e9e7}main{max-width:1100px;padding-top:42px}h1{font-size:28px;font-weight:550}.statusbar{display:flex;height:18px;gap:4px;margin:38px 0 14px;border-radius:4px;overflow:hidden}.decision{display:flex;gap:32px;align-items:center;margin:52px 0;padding:30px 0;border-bottom:1px solid var(--line)}.count{font-size:88px;line-height:1;color:#957040;letter-spacing:-.08em}.decision h2{font-size:24px;font-weight:500}.split{gap:42px}.split aside{padding-left:24px;border-left:1px solid var(--line)}',caveat='Это одна реализация рекомендаций, а не гарантированный результат каждого запуска скилла.')

diagram = '''<svg viewBox="0 0 960 480" role="img" aria-labelledby="flow-title flow-desc"><title id="flow-title">Результат возвращается владельцу работы</title><desc id="flow-desc">Оркестратор ставит задачу исполнителю. Исполнитель получает независимое ревью, разбирает замечания и передаёт результат оркестратору для приёмки.</desc><defs><marker id="flow-arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L8 4L0 8" fill="context-stroke"/></marker></defs><g fill="none" stroke="#78858c" stroke-width="2" marker-end="url(#flow-arrow)"><path d="M240 152H380"/><path d="M580 152H720"/><path d="M824 216V312Q824 320 816 320H580"/><path d="M380 320H148Q140 320 140 312V216"/></g><g font-size="12" fill="#647179"><text x="276" y="132">задача</text><text x="612" y="132">ревью</text><text x="648" y="300">замечания</text><text x="208" y="300">результат</text></g><rect x="40" y="88" width="200" height="128" rx="4" fill="#f0f2f3" stroke="#73818a"/><rect x="380" y="88" width="200" height="128" rx="4" fill="#fff" stroke="#33434a"/><rect x="720" y="88" width="208" height="128" rx="4" fill="#fff" stroke="#73818a"/><rect x="380" y="272" width="200" height="96" rx="4" fill="#fff1e8" stroke="#b45a20"/><g text-anchor="middle"><text x="140" y="140" font-size="20">Оркестратор</text><text x="140" y="176" font-size="16">принимает работу</text><text x="480" y="140" font-size="20">Исполнитель</text><text x="480" y="176" font-size="16">worker / full-cycle</text><text x="824" y="140" font-size="20">Ревьюер</text><text x="824" y="176" font-size="16">второе мнение</text><text x="480" y="312" font-size="20">Разбор замечаний</text><text x="480" y="344" font-size="16">у исполнителя</text></g><path d="M40 416H928" stroke="#d8dde0"/><text x="40" y="452" font-size="16">Стрелка — передача работы или результата</text><text x="592" y="452" font-size="16" style="fill:#b45a20">Акцент — кто отвечает за разбор</text></svg>'''
add('06-diagram','Схема ответственности','diagram-design','Связи от краёв блоков, ортогональные маршруты, один смысловой акцент и отдельная легенда.', '<main>'+HEADER+'<h1>Кто отвечает за результат</h1><p class="sub">Предлагаемое распределение обязанностей. Внешнее ревью запускается по принятой политике, а не для каждой задачи.</p><div class="diagram-scroll">'+diagram+'</div><p class="note">Владелец работы получает замечания и разбирает их. Оркестратор принимает результат по доказательствам.</p></main>', ':root{--bg:#f5f5f5;--ink:#2d3142;--mut:#65717b;--accent:#b45a20;--line:#d8dde0}h1{font:400 38px/1.15 Georgia,serif}.diagram-scroll{margin-top:32px;overflow:auto}.diagram-scroll svg{min-width:680px}.note{font-family:Georgia,serif;font-size:17px}',caveat='Шрифты заменены локальными для офлайна. Схема демонстрирует согласованное направление, а не утверждает, что запрет уже работает в сервисе.')

add('07-eli5','Объяснение картинкой','eli5','Крупный наглядный образ, минимум терминов, изменение входа сразу меняет результат.', '<main>'+HEADER+'<h1>Почему задачи ждут?</h1><p class="sub">Четыре рабочих места. На каждое помещается одна задача.</p><div class="queue-scene"><div class="queue" id="queue"></div><div class="gate">4 места</div><div class="workers" id="workers"></div></div><div class="row"><label for="arrival">Задач пришло</label><input id="arrival" type="range" min="1" max="10" value="6"><output id="arrival-value">6</output></div><p class="lesson" id="lesson"></p><p class="note">Упрощение: задачи одинаковые и выполняются одновременно. В реальной команде время и специализация различаются.</p></main>', ':root{--bg:#fff;--ink:#244a58;--mut:#5b717b;--accent:#188a93;--panel:#ecf7f7}main{max-width:1000px}h1{font:500 clamp(34px,5vw,52px)/1.1 Georgia,serif}.queue-scene{display:grid;grid-template-columns:1fr auto 1.3fr;align-items:center;gap:28px;min-height:300px}.queue,.workers{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.task{aspect-ratio:1.4;background:#deeeee;border:2px solid #74a7ac;border-radius:12px;display:grid;place-content:center;font-size:30px}.task.waiting{background:#fff1dc;border-color:#b98b46}.task.empty{background:#fafafa;border-style:dashed;opacity:.5}.gate{border-left:3px solid #769499;padding:32px 12px;font-size:20px}.lesson{font-size:28px;margin-top:30px;line-height:1.3}input{accent-color:#188a93}output{font-size:24px}@media(max-width:650px){.queue-scene{gap:12px}.task{font-size:20px}.gate{font-size:14px;padding:24px 6px}.lesson{font-size:24px}}', "const control=document.getElementById('arrival');function draw(){const n=+control.value;document.getElementById('arrival-value').value=n;document.getElementById('workers').innerHTML=Array.from({length:4},(_,i)=>'<div class=\"task '+(i<n?'':'empty')+'\">'+(i<n?'▤':'—')+'</div>').join('');document.getElementById('queue').innerHTML=Array.from({length:Math.max(0,n-4)},()=>'<div class=\"task waiting\">▤</div>').join('')||'<p>Очередь пуста</p>';document.getElementById('lesson').textContent=n>4?'В работе 4. В очереди '+(n-4)+'. Новая задача ждёт свободного места.':'Все '+n+' задачи поместились. Ждать не нужно.'}control.oninput=draw;draw();")

add('08-playground','Настройка плотности','playground','Живой образец, пресеты, регулировка отступов и скругления, экспорт решения словами.', '<main>'+HEADER+'<h1>Какой интерфейс тебе удобнее?</h1><p class="sub">Изменения сразу видны справа. Это можно забрать как инструкцию для будущего скилла.</p><div class="play-layout"><section class="controls"><label>Пресет<select id="preset"><option value="compact">Плотный белый</option><option value="soft">Мягкий и просторный</option><option value="strict">Строгий отчёт</option></select></label><label>Отступы <output id="padval">16</output><input id="pad" type="range" min="8" max="32" value="16"></label><label>Скругление <output id="radval">12</output><input id="rad" type="range" min="0" max="24" value="12"></label><label>Акцент<select id="accent"><option value="#007aff">Синий</option><option value="#28725a">Зелёный</option><option value="#815ba5">Сливовый</option></select></label></section><section id="preview"><h2>Команда за неделю</h2>'+metrics()+TABLE+'</section></div><div class="panel"><h2>Твоя инструкция</h2><p id="prompt"></p><button id="copy" class="primary" style="margin-top:16px">Скопировать инструкцию</button><p id="copy-status" role="status"></p></div></main>', ':root{--bg:#fff;--panel:#f5f5f7;--accent:#007aff;--mut:#666;--line:#ddd}.play-layout{display:grid;grid-template-columns:220px 1fr;gap:32px;margin:32px 0}.controls label{display:block;margin-bottom:24px;font-size:14px}.controls select,.controls input{display:block;width:100%;margin-top:8px}#preview{padding:24px;background:#f5f5f7;border-radius:16px;min-width:0}#preview .metric{background:white}#preview .grid{grid-template-columns:repeat(2,minmax(0,1fr))}#preview .metric strong{color:var(--accent)!important}@media(max-width:700px){.play-layout{grid-template-columns:1fr}.controls{display:grid;grid-template-columns:1fr 1fr;gap:16px}}', "const ids=['pad','rad','accent'];const defaults={pad:16,rad:12,accent:'#007aff'};const state={...defaults};function update(){ids.forEach(k=>state[k]=document.getElementById(k).value);document.getElementById('padval').value=state.pad;document.getElementById('radval').value=state.rad;document.querySelectorAll('#preview .metric').forEach(e=>{e.style.padding=state.pad+'px';e.style.borderRadius=state.rad+'px'});document.getElementById('preview').style.setProperty('--accent',state.accent);const details=[];if(+state.pad!==defaults.pad)details.push('отступы в панелях '+state.pad+' px');if(+state.rad!==defaults.rad)details.push('скругление '+state.rad+' px');if(state.accent!==defaults.accent)details.push('акцент '+document.getElementById('accent').selectedOptions[0].textContent.toLowerCase());document.getElementById('prompt').textContent='Сделай белый рабочий интерфейс с системным шрифтом, компактными метриками и спокойным фоном.'+(details.length?' Измени относительно плотного белого пресета: '+details.join(', ')+'.':' Оставь плотный белый пресет без изменений.')}ids.forEach(k=>document.getElementById(k).oninput=update);document.getElementById('preset').onchange=e=>{const p={compact:[16,12],soft:[28,22],strict:[10,2]}[e.target.value];document.getElementById('pad').value=p[0];document.getElementById('rad').value=p[1];document.getElementById('accent').value='#007aff';update()};document.getElementById('copy').onclick=async()=>{try{await navigator.clipboard.writeText(document.getElementById('prompt').textContent);document.getElementById('copy-status').textContent='Скопировано'}catch{document.getElementById('copy-status').textContent='Браузер не разрешил копирование. Выдели текст инструкции выше.'}};update();",caveat='Вместо обязательной тёмной оболочки исходного playground использован предпочитаемый тобой белый фон.')

