three_js = three + '''
;(()=>{const host=document.getElementById('scene');const reduced=matchMedia('(prefers-reduced-motion: reduce)');try{const scene=new THREE.Scene();scene.background=new THREE.Color('#f5f5f7');scene.fog=new THREE.FogExp2('#f5f5f7',.025);const camera=new THREE.PerspectiveCamera(50,1,.1,100);const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));host.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','Объёмная модель: 18 зелёных, 4 синих и 2 янтарных блока');renderer.domElement.setAttribute('role','img');scene.add(new THREE.AmbientLight(0xffffff,.8));const light=new THREE.DirectionalLight(0xffffff,1);light.position.set(5,8,8);scene.add(light);const group=new THREE.Group();scene.add(group);for(let i=0;i<24;i++){const material=new THREE.MeshStandardMaterial({color:i<18?0x76a393:i<22?0x789cce:0xd3aa71,roughness:.5});const cube=new THREE.Mesh(new THREE.BoxGeometry(.75,.75,.75),material);cube.position.set((i%4-1.5)*1.05,Math.floor(i/8)*1.05-.8,(Math.floor(i/4)%2-.5)*1.4);group.add(cube)}const floor=new THREE.Mesh(new THREE.PlaneGeometry(100,100),new THREE.MeshStandardMaterial({color:0xf5f5f7,roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-1.3;scene.add(floor);let current=0,target=0,frame=0;function render(){const angle=.6+current*1.6;camera.position.set(Math.sin(angle)*8,3+current*1.5,Math.cos(angle)*8);camera.lookAt(0,.1,0);renderer.render(scene,camera)}function step(){current+=(target-current)*.15;render();if(Math.abs(target-current)>.001)frame=requestAnimationFrame(step);else frame=0}function update(){target=scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight);if(reduced.matches){current=0;render()}else if(!frame)frame=requestAnimationFrame(step)}function resize(){renderer.setSize(host.clientWidth,host.clientHeight);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();render()}addEventListener('resize',resize);addEventListener('scroll',update,{passive:true});reduced.addEventListener('change',update);resize();update();document.getElementById('fallback').hidden=true;document.body.dataset.webgl='ready'}catch(e){document.getElementById('fallback').textContent='WebGL недоступен. Состав недели: 18 готово, 4 в работе, 2 ждут.';document.body.dataset.webgl='unavailable'}})();
'''
add('09-three','Объёмная история','3d-frontend','Настоящая сцена Three.js: камера движется при прокрутке, блоки показывают состав недели.', '<div id="scene"></div><main>'+HEADER+'<section class="chapter"><h1>Одна неделя.<br>Двадцать четыре задачи.</h1><p>Прокрути страницу — посмотри на работу с другой стороны.</p><p id="fallback">Загружается объёмная сцена…</p></section><section class="chapter"><h2>18 завершены</h2><p>Зелёные блоки — готовая работа.</p></section><section class="chapter"><h2>4 ещё в работе</h2><p>Синие блоки — текущие задачи.</p></section><section class="chapter"><h2>2 ждут решения</h2><p>Янтарные блоки — очередь к владельцу.</p><p class="small">Учебная иллюстрация. Для точного сравнения чисел лучше таблица.</p></section></main>', ':root{--bg:#f5f5f7;--ink:#263331;--mut:#64736f}#scene{position:fixed;inset:0 0 0 30%;z-index:0}#scene canvas{display:block}main{position:relative;pointer-events:none}.chapter{min-height:100vh;display:flex;justify-content:center;flex-direction:column;align-items:flex-start;max-width:440px}.chapter h1{font-size:clamp(32px,5vw,56px);font-weight:550}.chapter h2{font-size:42px}.chapter p{margin-top:20px;max-width:29ch}.chapter h1,.chapter h2,.chapter p{background:#f5f5f7e8;padding:8px;border-radius:8px}.demo{position:relative}.chapter:last-child{min-height:95vh}@media(max-width:650px){#scene{inset:15% 0 0 0}.chapter{justify-content:flex-start;padding-top:40px}.chapter h1{font-size:32px}.chapter h2{font-size:28px}.chapter p{max-width:27ch;font-size:14px}}@media print{#scene{display:none}.chapter{min-height:0;page-break-inside:avoid;padding:24px 0}}',three_js,caveat='Three.js встроен в HTML для офлайна. Привязка к скроллу написана без GSAP; при reduced motion камера неподвижна. 3D оставляем демонстрационным режимом, а не стандартом отчётов.')

add('10-cro','Страница с одним действием','page-cro + frontend-design','Понятная польза, одна основная кнопка, показ результата рядом, ответы на возражения.', '<main>'+HEADER+'<div class="landing"><section><h1>Увидеть, где<br>нужен человек.</h1><p class="sub">Один обзор команды: что завершено, что движется и какие решения ждут тебя.</p><button id="show-example" class="primary">Открыть учебный обзор</button><p class="small">Без регистрации. Данные вымышлены.</p></section><section class="product-preview"><p class="small">Команда за неделю</p>'+metrics()+'<h2>Ждут решения</h2><p>Оформление отчётов<br>Следующий этап</p></section></div><section id="opened" hidden class="panel"><h2>Примеры задач</h2>'+TABLE+'</section><div class="faq"><details><summary>Это реальные данные Orchestra?</summary><p>Нет. Это демонстрация оформления на учебных данных.</p></details><details><summary>Что делает кнопка?</summary><p>Показывает пример списка задач прямо на этой странице. Ничего не запускает в Orchestra.</p></details></div></main>', ':root{--bg:#fff;--ink:#1d1d1f;--mut:#6e6e73;--accent:#007aff;--panel:#f5f5f7;--line:#ddd}.landing{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center;min-height:490px}.landing h1{font-size:clamp(34px,5vw,58px);font-weight:600;line-height:1.07}.landing .sub{font-size:18px;margin:24px 0;max-width:35ch}.landing button{padding:13px 22px;border-radius:24px}.landing .small{margin-top:12px}.product-preview{background:#f5f5f7;padding:28px;border-radius:24px;transform:rotate(-2deg)}.product-preview .grid{grid-template-columns:1fr 1fr}.product-preview .metric{background:#fff}.faq{border-top:1px solid #ddd;margin-top:30px}details{padding:20px 0;border-bottom:1px solid #ddd}summary{cursor:pointer;font-weight:500}details p{margin-top:12px;color:#666}@media(max-width:700px){.landing{grid-template-columns:1fr;gap:24px}.product-preview{transform:none}}', "document.getElementById('show-example').onclick=()=>{const panel=document.getElementById('opened');panel.hidden=!panel.hidden;document.getElementById('show-example').textContent=panel.hidden?'Открыть учебный обзор':'Скрыть учебный обзор';if(!panel.hidden)panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})};",caveat='CRO отвечает за структуру и действие, а не за собственный визуальный стиль. Рост конверсии этим макетом не измерялся.')

