gallery_body='''<header class="gallery-header"><div><p class="small">Локальная коллекция / сентябрь 2026</p><h1>Выбираем язык оформления</h1><p class="sub">Десять новых примеров. Один учебный сюжет. Отметь, что оставить и что убрать.</p></div><button id="export" class="primary">Скачать мои оценки</button></header><nav id="nav" aria-label="Примеры дизайна"></nav><main class="gallery-main"><div class="sample-head"><div><h2 id="sample-title"></h2><p id="source" class="small"></p><p id="technique"></p><p id="caveat" class="small"></p></div><div class="row"><button id="narrow" aria-pressed="false">Узкий экран</button><button id="download">Скачать пример</button></div></div><div class="preview-wrap"><iframe id="frame" title="Интерактивный пример оформления" sandbox="allow-scripts allow-downloads"></iframe></div><div class="feedback"><div class="row"><strong>Твоя оценка</strong><button data-vote="yes">Оставить</button><button data-vote="no">Убрать</button><button data-vote="maybe">Доработать</button></div><label for="comment">Что нравится или мешает</label><textarea id="comment" rows="2" placeholder="Например: белый фон — да, заголовки мельче, больше плотности"></textarea><p id="save-status" class="small" role="status"></p></div><details class="collection"><summary>20 готовых шаблонов из кеша — посмотреть исходные превью</summary><p>Это оригинальные превью поставщика, не новые работы. Они относятся к DOCX, PPTX и XLSX; их стили можно оценить отдельно от HTML-примеров.</p><div id="templates"></div></details><details class="collection"><summary>Что найдено и как использовано</summary><p>Обследованы проектные .codex/.claude, глобальные .codex/.agents/.claude, кеши и локальные marketplace, каталог Projects/skills. Одинаковое содержимое объединено по SHA-256. Наличие в кеше не означает подключение к текущему агенту.</p><p>Применены все найденные самостоятельные направления веб-дизайна. HTML-копии с отличием только в пути и frontend-копии с отличием в финальной фразе показаны общим образцом. Форматные PDF/DOCX/PPTX/XLSX, imagegen, teach-me и udesign перечислены как смежные инструменты: они не задают отдельный стиль HTML. Нативные документы и растровые иллюстрации в этом сравнении не генерировались.</p><div id="inventory"></div></details><footer>Образцы созданы для выбора дизайна. Они не подключены к Orchestra и не изменяют её состояние. Оценки остаются в этом браузере; скачай их, чтобы передать обратно.</footer></main>'''
gallery_css='''
:root{--bg:#f5f5f7;--ink:#1d1d1f;--mut:#6e6e73;--panel:#fff;--accent:#007aff;--line:#dedee3}.gallery-header{padding:30px 36px 24px;background:#fff;display:flex;align-items:center;justify-content:space-between;gap:24px}.gallery-header h1{font-size:27px;margin:8px 0}.gallery-header .sub{font-size:14px}.gallery-header button{white-space:nowrap}nav{display:flex;gap:7px;padding:15px 36px;overflow:auto;border-bottom:1px solid #e2e2e7;background:#fff}nav button{white-space:nowrap;font-size:13px;padding:8px 13px;border:0;background:#f1f1f4}nav button[aria-current=true]{background:#1d1d1f;color:white}.gallery-main{max-width:1540px;padding:24px 36px}.sample-head{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:20px}.sample-head h2{margin-bottom:3px;font-size:21px}.sample-head #technique{font-size:14px;margin:8px 0 4px}#caveat{max-width:90ch}.preview-wrap{background:#e5e5ea;border:1px solid #dcdce1;border-radius:16px;padding:8px;display:flex;justify-content:center}iframe{border:0;background:#fff;border-radius:10px;width:100%;height:820px;transition:width .2s}iframe.narrow{width:390px}.feedback{background:white;padding:22px 24px;margin-top:16px;border-radius:14px}.feedback label{display:block;margin:16px 0 6px;font-size:13px}.feedback textarea{width:100%;resize:vertical;padding:12px;border:1px solid #ddd;border-radius:8px;font-size:14px;color:inherit}.feedback button[aria-pressed=true]{background:#007aff;color:white}.collection{padding:20px 0;border-bottom:1px solid #ddd}.collection summary{cursor:pointer;font-weight:550}.collection p{margin:12px 0;font-size:14px;color:#666}#templates{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:20px}.template{background:#fff;border:1px solid #ddd;border-radius:10px;padding:12px}.template img{width:100%;aspect-ratio:1.4;object-fit:contain;background:#fafafa;cursor:zoom-in}.template h3{font-size:14px;margin:12px 0}.template label{font-size:12px}.template select{width:100%;margin-top:8px}#inventory{overflow:auto}#inventory td{max-width:650px;overflow-wrap:anywhere;font-size:12px}#inventory td:last-child{text-align:left}footer{font-size:12px;color:#777;padding:24px 0}@media(max-width:700px){.gallery-header{padding:20px;align-items:flex-start;flex-direction:column}.gallery-header h1{font-size:24px}nav{padding:12px 20px}.gallery-main{padding:16px}.sample-head{flex-direction:column;align-items:flex-start}.preview-wrap{padding:3px}iframe{height:850px}#templates{grid-template-columns:1fr}.feedback{padding:16px}.feedback .row{gap:8px}.feedback strong{width:100%}}@media print{nav,.gallery-header button,.sample-head button,.feedback,.preview-wrap,.collection{display:none}.gallery-main{padding:0}}
'''
gallery_js='const DATA='+DATA+''';
(()=>{let current=0;let votes={};let storage=true;try{votes=JSON.parse(localStorage.getItem('design-gallery-v1')||'{}');if(!votes||typeof votes!=='object'||Array.isArray(votes))votes={}}catch{storage=false}const $=id=>document.getElementById(id);function save(){try{localStorage.setItem('design-gallery-v1',JSON.stringify(votes));$('save-status').textContent='Оценка сохранена в этом браузере.'}catch{storage=false;$('save-status').textContent='Браузер не сохраняет оценки. Скачай их кнопкой вверху.'}}function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function show(i){current=i;const s=DATA.samples[i];$('sample-title').textContent=s.title;$('source').textContent=s.source;$('technique').textContent=s.technique;$('caveat').textContent=s.caveat;$('frame').srcdoc=s.html;document.querySelectorAll('nav button').forEach((b,j)=>b.setAttribute('aria-current',String(i===j)));$('comment').value=votes[s.id]?.comment||'';document.querySelectorAll('[data-vote]').forEach(b=>b.setAttribute('aria-pressed',String(votes[s.id]?.vote===b.dataset.vote)));$('save-status').textContent=storage?'Оценки сохраняются локально.':'Чтобы сохранить оценки, скачай их.'}DATA.samples.forEach((s,i)=>{const b=document.createElement('button');b.textContent=(i+1)+'. '+s.title;b.onclick=()=>show(i);$('nav').append(b)});document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{const id=DATA.samples[current].id;votes[id]={...votes[id],vote:b.dataset.vote};save();document.querySelectorAll('[data-vote]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});$('comment').oninput=()=>{const id=DATA.samples[current].id;votes[id]={...votes[id],comment:$('comment').value};save()};$('narrow').onclick=()=>{const on=$('frame').classList.toggle('narrow');$('narrow').setAttribute('aria-pressed',String(on))};$('download').onclick=()=>{const s=DATA.samples[current];download(s.id+'.html',s.html,'text/html;charset=utf-8')};$('export').onclick=()=>download('design-preferences.json',JSON.stringify({version:1,reference:'https://photo-158-220-127-161.sslip.io/board/#stats',samples:DATA.samples.map(s=>({id:s.id,title:s.title,...votes[s.id]})),templates:DATA.templates.map((t,i)=>({title:t.name,...votes['template-'+i]}))},null,2),'application/json');DATA.templates.forEach((t,i)=>{const card=document.createElement('article');card.className='template';const img=document.createElement('img');img.src=t.image;img.alt='Исходное превью '+t.name;img.loading='lazy';img.onclick=()=>download(t.name+'.png',Uint8Array.from(atob(t.image.split(',')[1]),c=>c.charCodeAt(0)),'image/png');const heading=document.createElement('h3');heading.textContent=t.name;const label=document.createElement('label');label.textContent='Оценить оформление';const select=document.createElement('select');[['','Не оценено'],['yes','Нравится'],['no','Не нравится'],['maybe','Взять отдельные приёмы']].forEach(([v,l])=>select.add(new Option(l,v)));select.value=votes['template-'+i]?.vote||'';select.onchange=()=>{votes['template-'+i]={vote:select.value};save()};label.append(select);card.append(img,heading,label);$('templates').append(card)});const table=document.createElement('table');const head=table.createTHead().insertRow();['Источник','Размер SKILL.md','Копий','Расположение'].forEach(t=>{const th=document.createElement('th');th.textContent=t;head.append(th)});const tbody=table.createTBody();DATA.inventory.forEach(s=>{const row=tbody.insertRow();[s.name,s.bytes+' байт',s.paths.length,s.canonical].forEach(v=>row.insertCell().textContent=v)});$('inventory').append(table);show(0)})();
'''
